mapper.select:
SELECT id, storage_key, original_filename, content_type, size_bytes, sha256, status
  FROM voice_reference_assets
 WHERE account_id = #{accountId}
   AND id = #{id,typeHandler=com.narrativex.backend.feature.assets.infrastructure.persistence.mybatis.MediaAssetUuidTypeHandler}
   AND status <> 'DELETED'

SELECT EXISTS (
  SELECT 1 FROM voice_reference_assets WHERE storage_key = #{storageKey} AND status = 'READY'
)
